//! Autogenerated bindings for the core Vortex Protocol Buffers definitions.
//!
//! The schemas live in this crate's `proto` directory. Regenerate the bindings below with
//! `cargo xtask generate-proto` after changing them.

/// Data types.
///
/// `dtype.proto`:
/// ```protobuf
#[doc = include_str!("../proto/dtype.proto")]
/// ```
#[allow(clippy::all)]
#[allow(clippy::absolute_paths)]
#[allow(clippy::nursery)]
#[allow(missing_docs)]
#[rustfmt::skip]
#[path = "./generated/vortex.dtype.rs"]
pub mod dtype;

